解题思路是先设一个含 3 个元素的结构体数组，再用一个字符数组存放本次输入的姓名，然后与数组元素中的“姓名”成员逐个比较，相同就给该元素的“得票数”成员加 1：

```c
#include <stdio.h>
#include <string.h>

struct Person
{
    char name[20];
    int count;
} leader[3] = {"Li", 0, "Zhang", 0, "Sun", 0};

int main()
{
    int i, j;
    char leader_name[20];
    for (i = 1; i <= 10; i++)
    {
        scanf("%s", leader_name);
        for (j = 0; j < 3; j++)
            if (strcmp(leader_name, leader[j].name) == 0)
                leader[j].count++;
    }
    printf("\nResult:\n");
    for (i = 0; i < 3; i++)
        printf("%5s:%d\n", leader[i].name, leader[i].count);
    return 0;
}
```

输入 10 张选票上所写的被选人姓名后，程序输出各人的得票数。

```c
#include <stdio.h>

struct Student
{
    int num;
    char name[20];
    float score;
};

int main()
{
    struct Student stu[5] = {{10101, "Zhang", 78}, {10103, "Wang", 98.5}, {10106, "Li", 86},
                             {10108, "Ling", 73.5}, {10110, "Sun", 100}};
    struct Student temp;
    const int n = 5;
    int i, j, k;
    printf("The order is:\n");
    for (i = 0; i < n - 1; i++)
    {
        k = i;
        for (j = i + 1; j < n; j++)
            if (stu[j].score > stu[k].score)
                k = j;
        temp = stu[k]; stu[k] = stu[i]; stu[i] = temp;
    }
    for (i = 0; i < n; i++)
        printf("%6d %8s %6.2f\n", stu[i].num, stu[i].name, stu[i].score);
    printf("\n");
    return 0;
}
```

教材另作两点说明：程序中定义了常变量 `n`，运行期间它的值不能改变，若学生数改为 30 人只需改这一行；也可以不用常变量而用符号常量，取消该行并在文件开头加 `#define N 5`。此外，定义结构体数组时把每个学生的信息用一对花括号括起来，数据量多时阅读和检查都更方便。
